import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { createProperty, uploadImage } from '../services/api';
import { Upload, X } from 'lucide-react';
import styles from './PostPropertyPage.module.css';

const PROPERTY_TYPES = ['Apartment', 'Villa', 'Independent House', 'Plot / Land', 'Commercial', 'PG / Hostel'];
const LISTING_TYPES  = ['Sell', 'Rent'];
const FURNISHING     = ['Unfurnished', 'Semi-Furnished', 'Fully Furnished'];
const BEDROOMS       = ['1', '2', '3', '4', '5+'];

export default function PostPropertyPage() {
  const { user } = useAuth();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    title: '', location: '', city: '', locality: '', address: '',
    price: '', priceNote: '', perSqft: '', possession: 'Ready to Move',
    buildingType: 'Residential', listingType: 'Sell', propertyType: 'Apartment',
    userType: 'Owner', bedroom: '', bathroom: '', balconies: '',
    furnishingStatus: '', area: '', description: '',
    amenities: '', phone: '',
  });
  const [images,   setImages]   = useState([]);
  const [previews, setPreviews] = useState([]);
  const [loading,  setLoading]  = useState(false);
  const [error,    setError]    = useState('');
  const fileRef = useRef();

  if (!user) {
    navigate('/login'); return null;
  }

  const set = (key) => (e) => setForm(f => ({ ...f, [key]: e.target.value }));

  const handleFiles = (files) => {
    const arr = Array.from(files).slice(0, 10 - images.length);
    setImages(prev => [...prev, ...arr]);
    arr.forEach(file => {
      const reader = new FileReader();
      reader.onload = (e) => setPreviews(prev => [...prev, e.target.result]);
      reader.readAsDataURL(file);
    });
  };

  const removeImage = (i) => {
    setImages(prev => prev.filter((_, idx) => idx !== i));
    setPreviews(prev => prev.filter((_, idx) => idx !== i));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!form.title || !form.location || !form.price) {
      setError('Title, Location and Price are required.'); return;
    }
    setLoading(true);
    try {
      // Upload images
      const uploadedUrls = [];
      for (const file of images) {
        const { data } = await uploadImage(file);
        uploadedUrls.push(data.url);
      }
      const amenitiesArr = form.amenities.split(',').map(a => a.trim()).filter(Boolean);
      await createProperty({
        ...form,
        images: uploadedUrls,
        image: uploadedUrls[0] || '',
        amenities: amenitiesArr,
        secondaryCta: { label: 'Enquire', icon: 'phone-outline' },
      });
      navigate('/account?tab=listings');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to post. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`container ${styles.wrap}`}>
      <h1 className={styles.heading}>Post Your Property</h1>
      <p className={styles.sub}>Fill in the details below and your listing will be reviewed within 24 hours.</p>

      {error && <div className={styles.error}>{error}</div>}

      <form className={styles.form} onSubmit={handleSubmit}>
        {/* Basic Info */}
        <div className={styles.section}>
          <h2 className={styles.sectionTitle}>Basic Information</h2>
          <div className={styles.grid2}>
            <div className={styles.field}>
              <label className={styles.label}>Listing Type *</label>
              <select className={styles.select} value={form.listingType} onChange={set('listingType')}>
                {LISTING_TYPES.map(t => <option key={t} value={t}>{t === 'Sell' ? 'For Sale (Buy)' : 'For Rent'}</option>)}
              </select>
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Property Type *</label>
              <select className={styles.select} value={form.propertyType} onChange={set('propertyType')}>
                {PROPERTY_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
          </div>
          <div className={styles.field}>
            <label className={styles.label}>Property Title *</label>
            <input className={styles.input} placeholder="e.g. Spacious 3 BHK in Whitefield" value={form.title} onChange={set('title')} required />
          </div>
          <div className={styles.field}>
            <label className={styles.label}>Description</label>
            <textarea className={styles.textarea} rows={4} placeholder="Describe the property…" value={form.description} onChange={set('description')} />
          </div>
        </div>

        {/* Location */}
        <div className={styles.section}>
          <h2 className={styles.sectionTitle}>Location</h2>
          <div className={styles.grid2}>
            <div className={styles.field}>
              <label className={styles.label}>City *</label>
              <input className={styles.input} placeholder="Bengaluru" value={form.city} onChange={set('city')} />
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Locality</label>
              <input className={styles.input} placeholder="Whitefield" value={form.locality} onChange={set('locality')} />
            </div>
          </div>
          <div className={styles.field}>
            <label className={styles.label}>Full Location / Address *</label>
            <input className={styles.input} placeholder="e.g. Whitefield, Bengaluru, Karnataka" value={form.location} onChange={set('location')} required />
          </div>
        </div>

        {/* Pricing */}
        <div className={styles.section}>
          <h2 className={styles.sectionTitle}>Pricing</h2>
          <div className={styles.grid3}>
            <div className={styles.field}>
              <label className={styles.label}>Price *</label>
              <input className={styles.input} placeholder="₹85 Lakh" value={form.price} onChange={set('price')} required />
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Price Note</label>
              <input className={styles.input} placeholder="Negotiable" value={form.priceNote} onChange={set('priceNote')} />
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Per Sq.ft</label>
              <input className={styles.input} placeholder="₹7,500/sq.ft" value={form.perSqft} onChange={set('perSqft')} />
            </div>
          </div>
        </div>

        {/* Property Details */}
        <div className={styles.section}>
          <h2 className={styles.sectionTitle}>Property Details</h2>
          <div className={styles.grid3}>
            <div className={styles.field}>
              <label className={styles.label}>Bedrooms</label>
              <select className={styles.select} value={form.bedroom} onChange={set('bedroom')}>
                <option value="">Select</option>
                {BEDROOMS.map(b => <option key={b} value={b}>{b} BHK</option>)}
              </select>
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Bathrooms</label>
              <input className={styles.input} placeholder="2" value={form.bathroom} onChange={set('bathroom')} />
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Area (sq.ft)</label>
              <input className={styles.input} placeholder="1200 sq.ft" value={form.area} onChange={set('area')} />
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Furnishing</label>
              <select className={styles.select} value={form.furnishingStatus} onChange={set('furnishingStatus')}>
                <option value="">Select</option>
                {FURNISHING.map(f => <option key={f} value={f}>{f}</option>)}
              </select>
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Possession</label>
              <input className={styles.input} placeholder="Ready to Move" value={form.possession} onChange={set('possession')} />
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Contact Phone</label>
              <input className={styles.input} placeholder="+91 98765 43210" value={form.phone} onChange={set('phone')} />
            </div>
          </div>
          <div className={styles.field}>
            <label className={styles.label}>Amenities (comma separated)</label>
            <input className={styles.input} placeholder="Parking, Swimming Pool, Gym, 24/7 Security" value={form.amenities} onChange={set('amenities')} />
          </div>
        </div>

        {/* Photos */}
        <div className={styles.section}>
          <h2 className={styles.sectionTitle}>Photos (up to 10)</h2>
          <div
            className={styles.dropzone}
            onClick={() => fileRef.current.click()}
            onDragOver={e => e.preventDefault()}
            onDrop={e => { e.preventDefault(); handleFiles(e.dataTransfer.files); }}
          >
            <Upload size={28} className={styles.uploadIcon} />
            <div className={styles.dropLabel}>Click or drag photos here</div>
            <div className={styles.dropSub}>JPG, PNG, WebP — max 8MB each</div>
            <input ref={fileRef} type="file" multiple accept="image/*" style={{ display: 'none' }}
              onChange={e => handleFiles(e.target.files)} />
          </div>
          {previews.length > 0 && (
            <div className={styles.previewGrid}>
              {previews.map((src, i) => (
                <div key={i} className={styles.previewWrap}>
                  <img src={src} alt="" className={styles.previewImg} />
                  <button type="button" className={styles.removeImg} onClick={() => removeImage(i)}>
                    <X size={14} />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        <button type="submit" className={styles.submitBtn} disabled={loading}>
          {loading ? 'Submitting…' : 'Submit for Review →'}
        </button>
      </form>
    </div>
  );
}
